240	    /**
241	     * The owner's membership number, formatted {@code "<customerCode>-M<YY>"} where
242	     * YY is the last two digits of the registration date's year
243	     * (e.g. {@code "NSW-A1B2C3D4-M26"}). Derived from the owner's own fields; null when
244	     * either the customer code or registration date is absent.
245	     */
246	    @Transient
247	    public String getMembershipNumber() {
248	        if (this.customerCode == null || this.registrationDate == null) {
249	            return null;
250	        }
251	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
252	    }
253	
254	    /**
255	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
256	     * contained in the {@code customerCode}, scanning right to left and doubling the
257	     * rightmost digit first; non-digit characters are ignored. Derived from the owner's
258	     * own fields; null when the customer code is absent.
259	     */
260	    @Transient
261	    public Integer getCheckDigit() {
262	        if (this.customerCode == null) {
263	            return null;
264	        }
265	        int sum = 0;
266	        boolean dbl = true;
267	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
268	            char c = this.customerCode.charAt(i);
269	            if (c < '0' || c > '9') {
270	                continue;
271	            }
272	            int d = c - '0';
273	            if (dbl) {
274	                d *= 2;
275	                if (d > 9) {
276	                    d -= 9;
277	                }
278	            }
279	            sum += d;
280	            dbl = !dbl;
281	        }
282	        return (10 - (sum % 10)) % 10;
283	    }
284	
285	    /**
286	     * The owner's membership points: a running score built from the owner's own fields.
287	     * Starts at 0 and gains 2 when an email address is present, a further 1 when the owner
288	     * has no namesakes ({@code namesakeCount} is 0), a further 2 when it belongs to a
289	     * household of 3 or more members ({@code householdSize} is 3 or more), and a further 3
290	     * for tenure of more than 365 days (the days from {@link #registrationDate} to the
291	     * current date). A newly created owner has zero tenure, so the pre-tenure factors alone
292	     * top out at 5 points. Derived from the owner's own fields.
293	     */
294	    @Transient
295	    public Integer getMembershipPoints() {
296	        int points = 0;
297	        boolean hasEmail = this.email != null && !this.email.isBlank();
298	        if (hasEmail) {
299	            points += 2;
300	        }
301	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
302	        if (unique) {
303	            points += 1;
304	        }
305	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
306	        if (largeHousehold) {
307	            points += 2;
308	        }
309	        boolean tenured = this.registrationDate != null
310	            && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365;
311	        if (tenured) {
312	            points += 3;
313	        }
314	        return points;
315	    }
316	
317	    /**
318	     * The owner's membership level: a number from 1 to 4 derived by banding
319	     * {@link #getMembershipPoints()} — 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6
320	     * or more. Derived from the owner's own fields.
321	     */
322	    @Transient
323	    public Integer getMembershipLevel() {
324	        int points = getMembershipPoints();
325	        if (points <= 1) {
326	            return 1;
327	        }
328	        if (points <= 3) {
329	            return 2;
330	        }
331	        if (points <= 5) {
332	            return 3;
333	        }
334	        return 4;
335	    }
