535	    /**
536	     * Return the Pet with the given name, or null if none found for this Owner.
537	     *
538	     * @param name to test
539	     * @return true if pet name is already in use
540	     */
541	    public Pet getPet(String name, boolean ignoreNew) {
542	        name = name.toLowerCase();
543	        for (Pet pet : getPetsInternal()) {
544	            if (!ignoreNew || !pet.isNew()) {
545	                String compName = pet.getName();
546	                compName = compName.toLowerCase();
547	                if (compName.equals(name)) {
548	                    return pet;
549	                }
550	            }
551	        }
552	        return null;
553	    }
